var f = document.getElementById('reportsIFrame');
var doc = f.contentDocument || f.contentWindow.document;
var tbl = doc.querySelectorAll('table')[4];
var rows = tbl.querySelectorAll('tr');
var guests = [];
for (var i = 0; i < rows.length; i += 8) {
  function cellsOf(r) { return r ? Array.from(r.querySelectorAll('td,th')).map(function(c){return c.textContent.trim();}) : []; }
  var r0 = cellsOf(rows[i]);       // 來賓姓名 | name
  var r1 = cellsOf(rows[i+1]);     // 公司 | company
  var r2 = cellsOf(rows[i+2]);     // 職業 | profession | 電話 | phone
  var r3 = cellsOf(rows[i+3]);     // 分會 | chapter | 電子郵箱 | email
  var r4 = cellsOf(rows[i+4]);     // 訪問日期 | date
  var r5 = cellsOf(rows[i+5]);     // 邀請人 | invitedBy
  var r6 = cellsOf(rows[i+6]);     // Type | type
  if (!r0[1]) continue;
  guests.push({
    name: r0[1] || '',
    company: r1[1] || '',
    profession: r2[1] || '',
    phone: r2[3] || '',
    chapter: r3[1] || '',
    email: r3[3] || '',
    visitDate: r4[1] || '',
    invitedBy: r5[1] || '',
    type: r6[1] || ''
  });
}
window.__bniGuests = guests;
JSON.stringify({count: guests.length, sample: guests.slice(0,3)});

var blob = new Blob([JSON.stringify(window.__bniGuests)], {type: 'application/json'});
var url = URL.createObjectURL(blob);
var a = document.createElement('a');
a.href = url;
a.download = 'bni_guests_export.json';
document.body.appendChild(a);
a.click();
document.body.removeChild(a);
'download triggered, count=' + window.__bniGuests.length;

window.__bniGuestsCompact = window.__bniGuests.map(function(g){
